    """
    Implements a basic regex matching algorithm using recursion and dynamic programming.
    It supports literal characters, '.', '*', and '+'.
    """

    def is_match(p: str, t: str, memo: dict) -> bool:
        if (p, t) in memo:
            return memo[(p, t)]

        if not p:
            result = not t
        else:
            first_match = bool(t) and (p[0] == t[0] or p[0] == '.')

            if len(p) >= 2 and p[1] in {'*', '+'}:
                if p[1] == '*':
                    result = (is_match(p[2:], t, memo) or 
                              (first_match and is_match(p, t[1:], memo)))
                elif p[1] == '+':
                    result = (first_match and is_match(p, t[1:], memo))
            else:
                result = first_match and is_match(p[1:], t[1:], memo)

        memo[(p, t)] = result
        return result

    return is_match(pattern, text, {})

def match(pattern: str, text: str) -> bool:
    """
    Implements a basic regex matching algorithm using an iterative approach with a stack. 
    This implementation supports literal characters, '.', '*', and '+'.
    """

    def is_match_iter(p: str, t: str) -> bool:
        stack = [(0, 0)]  # (pattern index, text index)
        while stack:
            p_idx, t_idx = stack.pop()

            if p_idx == len(p) and t_idx == len(t):
                return True

            if p_idx < len(p):
                if t_idx < len(t) and (p[p_idx] == t[t_idx] or p[p_idx] == '.'):
                    stack.append((p_idx + 1, t_idx + 1))

                if p_idx + 1 < len(p):
                    if p[p_idx + 1] == '*':
                        stack.append((p_idx + 2, t_idx))  # zero occurrences
                        if t_idx < len(t) and (t[t_idx] == p[p_idx] or p[p_idx] == '.'):
                            stack.append((p_idx, t_idx + 1))  # more occurrences
                    elif p[p_idx + 1] == '+':
                        if t_idx < len(t) and (t[t_idx] == p[p_idx] or p[p_idx] == '.'):
                            stack.append((p_idx, t_idx + 1))  # one or more occurrences

            if p_idx == len(p) and t_idx < len(t):
                continue

        return False

    return is_match_iter(pattern, text)

