def match(pattern: str, text: str) -> bool:
    """
    Implements a basic regex matching algorithm using an iterative state machine approach.
    It supports literal characters, '.', '*', and '+'.
    """

    def matches(i: int, j: int) -> bool:
        if i == 0:
            return j == 0
        if j == 0:
            return i > 0 and pattern[i - 1] == '*' and matches(i - 2, j)

        if pattern[i - 1] == text[j - 1] or pattern[i - 1] == '.':
            return matches(i - 1, j - 1)
        elif pattern[i - 1] == '*':
            return matches(i - 2, j) or (matches(i, j - 1) and (pattern[i - 2] == text[j - 1] or pattern[i - 2] == '.'))
        elif pattern[i - 1] == '+':
            if j > 0 and (pattern[i - 2] == text[j - 1] or pattern[i - 2] == '.'):
                return matches(i, j - 1) or matches(i - 2, j - 1)

        return False

    return matches(len(pattern), len(text))

def match(pattern: str, text: str) -> bool:
    """
    Implements a basic regex matching algorithm using iterative dynamic programming.
    It supports literal characters, '.', '*', and '+'.
    """

    m, n = len(pattern), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        dp[0][j] = False  # Pattern can't match a non-empty text

    for i in range(1, m + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 2][0]  # Handle '*' as matching zero of previous element
        else:
            dp[i][0] = False  # Only literal characters or wildcard can count

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[i - 1] == text[j - 1] or pattern[i - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[i - 1] == '*':
                dp[i][j] = dp[i - 2][j] or (dp[i][j - 1] and (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.'))
            elif pattern[i - 1] == '+':
                dp[i][j] = dp[i - 1][j] and (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.') or (j > 0 and (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.') and dp[i][j - 1])

    return dp[m][n]
